def _detect_graphs_via_pystata(self) -> List[str]:
    """Detect newly created graphs using direct pystata state access."""
    if not self._stata_client:
        raise RuntimeError('Graph detector backend is unavailable')
    with self._lock:
        try:
            current_state = self._get_graph_state_from_pystata()
            current_graphs = list(current_state.keys())
            new_graphs = []
            for graph_name in current_graphs:
                if graph_name not in self._last_graph_state and graph_name not in self._removed_graphs:
                    new_graphs.append(graph_name)
            for graph_name, state in current_state.items():
                if graph_name in self._last_graph_state:
                    last_state = self._last_graph_state[graph_name]
                    if state.get('signature') != last_state.get('signature'):
                        if graph_name not in self._removed_graphs:
                            new_graphs.append(graph_name)
            self._last_graph_state = current_state.copy()
            return new_graphs
        except (ImportError, RuntimeError, ValueError, AttributeError) as e:
            raise
        except Exception as e:
            raise

def detect_graph_modifications(self, text: str=None) -> dict:
    """Detect graph modification/removal using SFI state comparison."""
    modifications = {'dropped': [], 'renamed': [], 'cleared': False}
    if not self._stata_client:
        raise RuntimeError('Graph detector backend is unavailable')
    try:
        new_state = self._get_graph_state_from_pystata()
        current_graphs = set(new_state.keys())
        if self._last_graph_state:
            last_graphs = set(self._last_graph_state.keys())
            dropped_graphs = last_graphs - current_graphs
            modifications['dropped'].extend(dropped_graphs)
            if last_graphs and (not current_graphs):
                modifications['cleared'] = True
        self._last_graph_state = new_state
    except Exception as e:
        raise
    return modifications

async def _run_owned_graph_call(self, function, *args):
    # Workbench graph threads drain under both AnyIO and asyncio cancellation.
    # asyncio.to_thread alone abandons its real thread when its waiter cancels.
    import anyio
    cancellation = None
    with anyio.CancelScope(shield=True):
        worker = asyncio.create_task(asyncio.to_thread(function, *args))
        while not worker.done():
            try:
                # wait() cancellation never cancels its input tasks and does
                # not create abandoned shield futures that report worker errors.
                await asyncio.wait({worker})
            except asyncio.CancelledError as error:
                cancellation = error
    if cancellation is not None:
        # Retrieve any worker error before propagating the caller's cancel.
        if not worker.cancelled():
            worker.exception()
        raise cancellation
    # Deliver deferred AnyIO cancellation even when the drained worker failed.
    try:
        await anyio.lowlevel.checkpoint()
    except asyncio.CancelledError:
        # Cancellation wins, but the worker's exception must still be consumed.
        if not worker.cancelled():
            worker.exception()
        raise
    return worker.result()

async def _cache_pending_graphs(self) -> List[str]:
    # Workbench graph failures propagate; unfinished cache entries remain pending.
    with self._lock:
        pending = list(dict.fromkeys(self._graphs_to_cache))
        self._graphs_to_cache.clear()
    if not pending:
        return []
    cached_names = []
    try:
        current = await self._run_owned_graph_call(self.stata_client.list_graphs)
        for name in pending:
            if name not in current or name in self._cached_graphs or name in self._removed_graphs:
                continue
            try:
                success = await self._run_owned_graph_call(self.stata_client.cache_graph_on_creation, name)
                if success is not True:
                    raise RuntimeError("Graph cache did not succeed: " + name)
            except Exception as error:
                try:
                    await self._notify_cache_callbacks(name, False)
                except Exception as callback_error:
                    raise ExceptionGroup("Graph cache and failure callbacks failed",
                                         [error, callback_error]) from None
                raise
            with self._lock:
                self._cached_graphs.add(name)
            cached_names.append(name)
            await self._notify_cache_callbacks(name, True)
        return cached_names
    except BaseException:
        # Keep pending work on failure/cancel without re-running the user command.
        with self._lock:
            remaining = [name for name in pending
                         if name not in self._cached_graphs and name not in self._removed_graphs]
            self._graphs_to_cache = list(dict.fromkeys(remaining + self._graphs_to_cache))
        raise

async def cache_detected_graphs_with_pystata(self) -> List[str]:
    if not self.auto_cache:
        return []
    if self.stata_client:
        self.detector._inventory_cache_enabled = True
        try:
            detected = await self._run_owned_graph_call(self.detector._detect_graphs_via_pystata)
        finally:
            self.detector._inventory_cache_enabled = False
        with self._lock:
            for name in detected:
                if name not in self._cached_graphs and name not in self._removed_graphs:
                    self._graphs_to_cache.append(name)
    return await self._cache_pending_graphs()

async def cache_detected_graphs(self) -> List[str]:
    if not self.auto_cache:
        return []
    return await self._cache_pending_graphs()

def _get_graph_state_from_pystata(self) -> Dict[str, Any]:
    """Get detailed graph state information using pystata's sfi interface."""
    graph_state = {}
    try:
        current_graphs, timestamps = self._get_graph_inventory()
        cmd_idx = getattr(self._stata_client, '_command_idx', 0)
        for graph_name in current_graphs:
            try:
                fast_sig = self._describe_graph_signature(graph_name)
                prev = self._last_graph_state.get(graph_name)
                timestamp = timestamps.get(graph_name)
                if prev and prev.get('cmd_idx') == cmd_idx:
                    sig = prev.get('signature')
                elif timestamp:
                    sig = f'{graph_name}_{timestamp}'
                else:
                    sig = fast_sig
                state_info = {'name': graph_name, 'exists': True, 'valid': bool(sig), 'signature': sig, 'cmd_idx': cmd_idx, 'timestamp_val': timestamp}
                if prev is None or prev.get('signature') != sig:
                    state_info['timestamp'] = time.time()
                else:
                    state_info['timestamp'] = prev.get('timestamp', time.time())
                graph_state[graph_name] = state_info
            except Exception as e:
                raise
    except Exception as e:
        raise
    return graph_state

